function hk(h, fist, grip, relaxed, open) { return h < 0 ? grip + (fist - grip) * Math.min(1, -h) : h < 1 ? grip + (relaxed - grip) * h : relaxed + (open - relaxed) * Math.min(1, h - 1); }
