/** Keyed curve through keys with Catmull-Rom tangents (fluid, no stops at keys; flat at the ends). */
function kc(t, T, V) {
  const n = T.length; if (t <= T[0]) return V[0]; if (t >= T[n - 1]) return V[n - 1];
  let i = 1; while (T[i] < t) i++;
