  const m0 = i > 1 ? (V[i] - V[i - 2]) / (T[i] - T[i - 2]) : 0;
  const m1 = i < n - 1 ? (V[i + 1] - V[i - 1]) / (T[i + 1] - T[i - 1]) : 0;
