      // hunches forward. The stabilised head stays level, so the lean reads as drive, not as falling over.
      const lean = gw * (lerp(0.05, 0.3, rn) * (1 - bk * 1.3) * (1 - 0.55 * this.wAim) + 0.14 * this.wGoo);
