    const rk = gw * this.runW;
    if (rk > 0.001) {
      if (H.run) { lerpE(P, ANC, H.run.p[0], H.run.p[1] + 0.012 * carryPulse, H.run.p[2] - swA * 0.08, rk); lerpE(P, ANCR, H.run.r[0] + swA * 0.4, H.run.r[1], H.run.r[2], rk); }
      else { P[ANC + 1] += 0.025 * rk; P[ANC + 2] += 0.04 * rk; P[ANCR] -= 0.18 * rk; }
    }
