    const A = armSpec(s);
    const s0 = 0.03, s1 = A.sW + 0.022;
    const ss = K.densitySamples(nS, s0, s1, (x) => 1 + 1.6 * gauss(x - A.sE, 0.03) + 1.2 * gauss(x - A.sW, 0.02) + 0.6 * gauss(x - 0.105, 0.02));
