    k -= 0.055 * gauss(s2 - sK + 0.004, 0.022) * (1 - Math.abs(n)) ** 2;                             // knee waist (sides)
    k -= 0.06 * gauss(s2 - sK - 0.004, 0.02) * back ** 3;                                             // popliteal hollow
