function addLegs(B, lv) {
  const [nTh, nS] = RES[lv].leg;
  for (const s of ['L', 'R']) {
    const Lg = legSpec2(s);
    const s0 = 0.03, s1 = Lg.sA + 0.03;
    const ss = K.densitySamples(nS, s0, s1, (x) => 1 + 1.8 * gauss(x - Lg.sK, 0.04) + 0.5 * gauss(x - Lg.sK - 0.06, 0.04) + 0.3 * gauss(x - 0.17, 0.03));
