  const hemRows = [[TEE_HEM + 0.013, -0.0046], [TEE_HEM + 0.004, -0.0048], [TEE_HEM - 0.0006, -0.0042], [TEE_HEM - 0.0021, -0.0024], [TEE_HEM - 0.0012, -0.0005]];
