// ---- rib crew collar: a double-layer band standing on the neckline, leaning in toward the neck ---------------------
function addTeeCollar(B, lv, ringAt) {
  const [nC, nPsi0] = RES[lv].collar; const nPsi = nPsi0 + 4;
