/** Tee weights for hardware riding on the tee (no hem flap). */
function onTeeWeights(p) { return teeWeights(p).filter((e) => e[0] !== 'hemF' && e[0] !== 'hemB'); }

function addHarness(B, lv) {
  const R = RES[lv];
